# Surah Al-Anfal (chapter 8) — part 7: ayat 59-68 (IDs 1219-1228)
SURAH = 8

ENTRIES = {
1219: (
"اور — جنہوں نے کفر کیا — ہرگز یہ گمان نہ کریں کہ وہ سبقت کر گئے — بے شک — وہ — ہماری قدرت سے — عاجز — نہیں",
"""۱۔ کفار ہماری گرفت سے — بچ نہیں سکتے۔
۲۔ ’’وَلَا يَحْسَبَنَّ الَّذِينَ كَفَرُوا سَبَقُوا إِنَّهُمْ لَا يُعْجِزُونَ‘‘ — اور — جنہوں نے کفر کیا — ہرگز یہ گمان نہ کریں کہ وہ سبقت کر گئے — بے شک — وہ — ہماری قدرت سے — عاجز — نہیں — یعنی کفار — جو بچ گئے — وہ — اللہ سے — بچ نہیں سکے۔
۳۔ عملی سبق: اللہ کی گرفت سے — کوئی بچ نہیں سکتا۔"""
),
1220: (
"اور — ان کے مقابلے کے لیے — قوت اور — گھوڑوں کی نگرانی — تیار کرو — جس سے — تم — اللہ کے دشمن اور تمہارے دشمن — اور ان کے علاوہ — دوسروں کو — جنہیں تم نہیں جانتے — انہیں اللہ جانتا ہے — خوفزدہ کرو — اور — جو کچھ — تم — اللہ کی راہ میں — خرچ کرو — تمہیں پورا دیا جائے گا — اور — تم پر — ظلم نہیں کیا جائے گا",
"""۱۔ جہاد کے لیے — مکمل تیاری — واجب۔
۲۔ ’’وَأَعِدُّوا لَهُم مَّا اسْتَطَعْتُم مِّن قُوَّۃٍ وَمِن رِّبَاطِ الْخَيْلِ تُرْهِبُونَ بِهِ عَدُوَّ اللَّهِ وَعَدُوَّكُمْ وَآخَرِينَ مِن دُونِهِمْ لَا تَعْلَمُونَهُمُ اللَّهُ يَعْلَمُهُمْ وَمَا تُنفِقُوا مِن شَيْءٍ فِي سَبِيلِ اللَّهِ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ‘‘ — اور — ان کے مقابلے کے لیے — قوت اور — گھوڑوں کی نگرانی — تیار کرو — جس سے — تم — اللہ کے دشمن اور تمہارے دشمن — اور ان کے علاوہ — دوسروں کو — جنہیں تم نہیں جانتے — انہیں اللہ جانتا ہے — خوفزدہ کرو — اور — جو کچھ — تم — اللہ کی راہ میں — خرچ کرو — تمہیں پورا دیا جائے گا — اور — تم پر — ظلم نہیں کیا جائے گا — یعنی قوت کی ہر شکل — فوجی، مالی، ذہنی — تیار رکھو۔
۳۔ عملی سبق: اللہ کی راہ میں — تیاری اور خرچ — ہی کامیابی کا راز ہے۔"""
),
1221: (
"اور — اگر — وہ — صلح — کی طرف — جھکیں — تو — تم بھی اس — طرف — جھکو — اور — اللہ پر توکل کرو — بے شک — وہ — سننے والا جاننے والا ہے",
"""۱۔ صلح کی طرف — مؤمنین کے لیے — اولیت۔
۲۔ ’’وَإِن جَنَحُوا لِلسَّلْمِ فَاجْنَحْ لَهَا وَتَوَكَّلْ عَلَى اللَّهِ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ‘‘ — اور — اگر — وہ — صلح — کی طرف — جھکیں — تو — تم بھی اس — طرف — جھکو — اور — اللہ پر توکل کرو — بے شک — وہ — سننے والا جاننے والا ہے — یعنی صلح — جنگ سے بہتر ہے — مگر — اللہ پر توکل کے بغیر — نہیں۔
۳۔ عملی سبق: صلح کا موقع — کبھی — نہ ٹھکراؤ۔"""
),
1222: (
"اور — اگر — وہ — تم سے — فریب — کرنا چاہیں — تو — اللہ — تمہارے لیے کافی ہے — وہی — ہے جس نے — اپنی مدد سے — اور — مؤمنوں کے ذریعے — تمہاری تائید کی",
"""۱۔ اللہ — ہر فریب سے بچاؤ — کافی ہے۔
۲۔ ’’وَإِن يُرِيدُوا أَن يَخْدَعُوكَ فَإِنَّ حَسْبَكَ اللَّهُ هُوَ الَّذِي أَيَّدَكَ بِنَصْرِهِ وَبِالْمُؤْمِنِينَ‘‘ — اور — اگر — وہ — تم سے — فریب — کرنا چاہیں — تو — اللہ — تمہارے لیے کافی ہے — وہی — ہے جس نے — اپنی مدد سے — اور — مؤمنوں کے ذریعے — تمہاری تائید کی — یعنی کافروں کے فریب سے — اللہ کی حفاظت — ہی بچاؤ ہے۔
۳۔ عملی سبق: کسی بھی فریب سے — اللہ کی پناہ — سب سے کافی ہے۔"""
),
1223: (
"اور — ان کے دلوں — میں — الفت — پیدا کی — اگر — تم زمین — کی ساری دولت — خرچ کرتے — تو — تم — ان کے دلوں — میں — الفت — پیدا نہیں کر سکتے تھے — لیکن — اللہ نے — ان کے دلوں — میں — الفت پیدا کی — بے شک — وہ — زبردست حکمت والا ہے",
"""۱۔ مؤمنوں کے دلوں میں — اللہ کی پیدا کردہ الفت۔
۲۔ ’’وَأَلَّفَ بَيْنَ قُلُوبِهِمْ لَوْ أَنفَقْتَ مَا فِي الْأَرْضِ جَمِيعًا مَّا أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَٰكِنَّ اللَّهَ أَلَّفَ بَيْنَهُمْ إِنَّهُ عَزِيزٌ حَكِيمٌ‘‘ — اور — ان کے دلوں — میں — الفت — پیدا کی — اگر — تم زمین — کی ساری دولت — خرچ کرتے — تو — تم — ان کے دلوں — میں — الفت — پیدا نہیں کر سکتے تھے — لیکن — اللہ نے — ان کے دلوں — میں — الفت پیدا کی — بے شک — وہ — زبردست حکمت والا ہے — یعنی مؤمنوں کا اتحاد — انسانی طاقت سے نہیں — اللہ کی طرف سے ہے۔
۳۔ عملی سبق: اتحاد — اللہ کی نعمت ہے؛ اسے — سنبھال کر رکھو۔"""
),
1224: (
"اے نبیؐ — اللہ — تمہیں اور — ان — مؤمنوں کو جو — تمہاری پیروی کرتے ہیں — کافی ہے",
"""۱۔ اللہ — نبیؐ اور مؤمنوں — کا سب سے بڑا پشت پناہ۔
۲۔ ’’يَا أَيُّهَا النَّبِيُّ حَسْبُكَ اللَّهُ وَمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِنِينَ‘‘ — اے نبیؐ — اللہ — تمہیں اور — ان — مؤمنوں کو جو — تمہاری پیروی کرتے ہیں — کافی ہے — یعنی اللہ — نبیؐ اور ان کے پیروਕਾਰوں — کا سب سے بڑا سینہ — بنا ہے۔
۳۔ عملی سبق: اللہ — سب سے کافی ہتھیار ہے۔"""
),
1225: (
"اے نبیؐ — مؤمنوں کو — جنگ — کی ترغیب دو — اگر — تم میں — بیس — صبر کرنے والے ہوں — وہ — دو سو پر غالب آئیں گے — اور — اگر — تم میں — ایک سو ہوں — وہ — کافروں کے ایک ہزار پر غالب آئیں گے — اس لیے کہ وہ — ایسی قوم ہیں — جو نہیں سمجھتے",
"""۱۔ مؤمنوں کی طاقت — مقدار نہیں — ایمان ہے۔
۲۔ ’’يَا أَيُّهَا النَّبِيُّ حَرِّضِ الْمُؤْمِنِينَ عَلَى الْقِتَالِ إِن يَكُن مِّنكُمْ عِشْرُونَ صَابِرُونَ يَغْلِبُوا مِائَتَيْنِ وَإِن يَكُن مِّنكُم مِّائَۃٌ يَغْلِبُوا أَلْفًا مِّنَ الَّذِينَ كَفَرُوا بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ‘‘ — اے نبیؐ — مؤمنوں کو — جنگ — کی ترغیب دو — اگر — تم میں — بیس — صبر کرنے والے ہوں — وہ — دو سو پر غالب آئیں گے — اور — اگر — تم میں — ایک سو ہوں — وہ — کافروں کے ایک ہزار پر غالب آئیں گے — اس لیے کہ وہ — ایسی قوم ہیں — جو نہیں سمجھتے — یعنی مؤمن — کم تعداد میں — بھی — ایمان اور صبر سے — زیادہ کاموں پر — غالب آ جائیں گے۔
۳۔ عملی سبق: ایمان اور صبر — سب سے بڑی طاقت ہیں۔"""
),
1226: (
"اب — اللہ — نے — تمہارا بوجھ — ہلکا کر دیا — اور — جانا — کہ — تم میں — کمزوری ہے — پس — اگر — تم میں — سو — صبر کرنے والے ہوں — وہ — دو سو پر غالب آئیں گے — اور — اگر — تم میں — ایک ہزار ہوں — وہ — اللہ کی اجازت سے — دو ہزار پر غالب آئیں گے — اور — اللہ — صبر کرنے والوں کے ساتھ ہے",
"""۱۔ اصل نسبت — ایک — دو ہزار۔
۲۔ ’’الْآنَ خَفَّفَ اللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًا فَإِن يَكُن مِّنكُم مِّائَۃٌ صَابِرَۃٌ يَغْلِبُوا مِائَتَيْنِ وَإِن يَكُن مِّنكُمْ أَلْفٌ يَغْلِبُوا أَلْفَيْنِ بِإِذْنِ اللَّهِ وَاللَّهُ مَعَ الصَّابِرِينَ‘‘ — اب — اللہ — نے — تمہارا بوجھ — ہلکا کر دیا — اور — جانا — کہ — تم میں — کمزوری ہے — پس — اگر — تم میں — سو — صبر کرنے والے ہوں — وہ — دو سو پر غالب آئیں گے — اور — اگر — تم میں — ایک ہزار ہوں — وہ — اللہ کی اجازت سے — دو ہزار پر غالب آئیں گے — اور — اللہ — صبر کرنے والوں کے ساتھ ہے — یعنی اللہ — کمزور حالات میں — نرم حدیں — مقرر کرتا ہے — مگر — اللہ — صبر کرنے والوں کے ساتھ — ہی رہتا ہے۔
۳۔ عملی سبق: اللہ — ہر حال میں — تمہاری طاقت کے مطابق — حکم کرتا ہے۔"""
),
1227: (
"نبیؐ — کے لیے — جائز نہیں کہ — اس کے — قیدی — ہوں — جب تک — وہ — زمین میں — خوب — جنگ — نہ کرے — تم — دنیا کی — عارضی چیز — چاہتے ہو — اور — اللہ — آخرت چاہتا ہے — اور — اللہ — زبردست حکمت والا ہے",
"""۱۔ قیدیوں سے پہلے — زمین پر — مکمل غلبہ۔
۲۔ ’’مَا كَانَ لِنَبِيٍّ أَن يَكُونَ لَهُ أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِي الْأَرْضِ تُرِيدُونَ عَرَضَ الدُّنْيَا وَاللَّهُ يُرِيدُ الْآخِرَۃَ وَاللَّهُ عَزِيزٌ حَكِيمٌ‘‘ — نبیؐ — کے لیے — جائز نہیں کہ — اس کے — قیدی — ہوں — جب تک — وہ — زمین میں — خوب — جنگ — نہ کرے — تم — دنیا کی — عارضی چیز — چاہتے ہو — اور — اللہ — آخرت چاہتا ہے — اور — اللہ — زبردست حکمت والا ہے — یعنی قیدیوں کی فکر — مالِ غنیمت کی لالچ سے پہلے نہیں — پہلے — زمین میں غلبہ — لازم ہے۔
۳۔ عملی سبق: مال کی لالچ — اصل مقصد سے — دور لے جاتی ہے۔"""
),
1228: (
"اگر — اللہ کی طرف سے — پہلے سے — تحریر — نہ ہوتی — تو — تمہیں — اس میں — جو تم نے — حاصل کیا — بڑا عذاب — پہنچتا",
"""۱۔ بدر کی غنیمت — اللہ کی پہلے سے مقرر رحمت۔
۲۔ ’’لَّوْلَا كِتَابٌ مِّنَ اللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَا أَخَذْتُمْ عَذَابٌ عَظِيمٌ‘‘ — اگر — اللہ کی طرف سے — پہلے سے — تحریر — نہ ہوتی — تو — تمہیں — اس میں — جو تم نے — حاصل کیا — بڑا عذاب — پہنچتا — یعنی اللہ نے پہلے سے مقرر کیا تھا کہ — غنیمت — مؤمنوں کے لیے حلال ہے — ورنہ — بدر میں — قیدیوں کے بدلے — فدیہ — سنگین سزا — کا سبب بنتا۔
۳۔ عملی سبق: اللہ کے احکام — سب کچھ پہلے سے مقرر ہے — انہیں جھٹلاؤ نہیں۔"""
),
}
